// FUNCTION: BFME2 0x00198C60 size=209 name=?Which_Side@AABTreeBuilderClass@@AAE?AW4OverlapType@1@ABVAAPlaneClass@@H@Z evidence=N:ledger tier=L hypothesis:name:L
AABTreeBuilderClass::OverlapType AABTreeBuilderClass::Which_Side(const AAPlaneClass &plane, int poly_index)
{
	int mask = 0;

	for (int vi = 0; vi < 3; vi++) {
		const Vector3 &point = Verts[Polys[poly_index][vi]];
		float delta = point[plane.Normal] - plane.Dist;

		if (delta > COINCIDENCE_EPSILON) {
			mask |= POS;
		}
		if (delta < -COINCIDENCE_EPSILON) {
			mask |= NEG;
		}
		mask |= ON;
	}

	// check results
	if (mask == ON) {
		return ON;
	}

	if ((mask & ~(POS | ON)) == 0) {
		return POS;
	}

	if ((mask & ~(NEG | ON)) == 0) {
		return NEG;
	}

	return BOTH;
}

// FUNCTION: BFME2 0x00198D40 size=168 name=?Split_Polys@AABTreeBuilderClass@@AAEXHPAHABUSplitChoiceStruct@1@PAUSplitArraysStruct@1@@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Split_Polys(int polycount, int *polyindices, const SplitChoiceStruct &sc, SplitArraysStruct *arrays)
{
	// Note: the caller is responsible for deleting the arrays inside the SplitArraysStruct
	if (sc.FrontCount > 0) {
		arrays->FrontPolys = new int[sc.FrontCount];
	}

	if (sc.BackCount > 0) {
		arrays->BackPolys = new int[sc.BackCount];
	}

	arrays->FrontCount = 0;
	arrays->BackCount = 0;

	// loop through all polys, sticking them into the appropriate array
	for (int i = 0; i < polycount; i++) {
		switch (Which_Side(sc.Plane, polyindices[i])) {
		case FRONT:
		case ON:
		case BOTH:
			arrays->FrontPolys[arrays->FrontCount++] = polyindices[i];
			break;

		case BACK:
			arrays->BackPolys[arrays->BackCount++] = polyindices[i];
			break;
		}
	}
}

// FUNCTION: BFME2 0x00198E00 size=54 name=?Assign_Index@AABTreeBuilderClass@@AAEHPAUCullNodeStruct@1@H@Z evidence=N:ledger tier=L hypothesis:name:L
int AABTreeBuilderClass::Assign_Index(CullNodeStruct *node, int index)
{
	// assign the next index to this node
	node->Index = index;
	index++;

	// assign indices to our children
	if (node->Front) {
		index = Assign_Index(node->Front, index);
	}
	if (node->Back) {
		index = Assign_Index(node->Back, index);
	}

	return index;
}

// FUNCTION: BFME2 0x00198E40 size=52 name=?Node_Count_Recursive@AABTreeBuilderClass@@AAEHPAUCullNodeStruct@1@H@Z evidence=N:ledger tier=L hypothesis:name:L
int AABTreeBuilderClass::Node_Count_Recursive(CullNodeStruct *node, int curcount)
{
	curcount++;
	if (node->Front) {
		curcount = Node_Count_Recursive(node->Front, curcount);
	}
	if (node->Back) {
		curcount = Node_Count_Recursive(node->Back, curcount);
	}
	return curcount;
}

// FUNCTION: BFME2 0x00198E80 size=211 name=?Update_Min@AABTreeBuilderClass@@AAEXHAAVVector3@@@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Update_Min(int poly_index, Vector3 &min)
{
	for (int vert_index = 0; vert_index < 3; vert_index++) {
		const TriIndex *polyverts = Polys + poly_index;
		const Vector3 *point = Verts + (*polyverts)[vert_index];
		if (point->X < min.X) min.X = point->X;
		if (point->Y < min.Y) min.Y = point->Y;
		if (point->Z < min.Z) min.Z = point->Z;
	}
}

// FUNCTION: BFME2 0x00198F60 size=212 name=?Update_Max@AABTreeBuilderClass@@AAEXHAAVVector3@@@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Update_Max(int poly_index, Vector3 &max)
{
	for (int vert_index = 0; vert_index < 3; vert_index++) {
		const TriIndex *polyverts = Polys + poly_index;
		const Vector3 *point = Verts + (*polyverts)[vert_index];
		if (point->X > max.X) max.X = point->X;
		if (point->Y > max.Y) max.Y = point->Y;
		if (point->Z > max.Z) max.Z = point->Z;
	}
}

// FUNCTION: BFME2 0x00199040 size=358 name=?Update_Min_Max@AABTreeBuilderClass@@AAEXHAAVVector3@@0@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Update_Min_Max(int poly_index, Vector3 &min, Vector3 &max)
{
	for (int vert_index = 0; vert_index < 3; vert_index++) {
		const TriIndex *polyverts = Polys + poly_index;
		const Vector3 *point = Verts + (*polyverts)[vert_index];
		if (point->X < min.X) min.X = point->X;
		if (point->Y < min.Y) min.Y = point->Y;
		if (point->Z < min.Z) min.Z = point->Z;
		if (point->X > max.X) max.X = point->X;
		if (point->Y > max.Y) max.Y = point->Y;
		if (point->Z > max.Z) max.Z = point->Z;
	}
}

// FUNCTION: BFME2 0x001991B0 size=183 name=?Build_W3D_AABTree_Recursive@AABTreeBuilderClass@@AAEXPAUCullNodeStruct@1@PAUW3dMeshAABTreeNode@@PAKAAH3@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Build_W3D_AABTree_Recursive(AABTreeBuilderClass::CullNodeStruct *node, W3dMeshAABTreeNode *w3d_nodes, unsigned long *poly_indices, int &cur_node, int &cur_poly)
{
	// Copy data from the builder's node into our node
	W3dMeshAABTreeNode *newnode = &(w3d_nodes[node->Index]);
	newnode->Min.X = node->Min.X;
	newnode->Min.Y = node->Min.Y;
	newnode->Min.Z = node->Min.Z;
	newnode->Max.X = node->Max.X;
	newnode->Max.Y = node->Max.Y;
	newnode->Max.Z = node->Max.Z;

	// If this is a non-leaf node, set up the child indices, otherwise set up the polygon indices
	if (node->Front != NULL) {
		newnode->FrontOrPoly0 = node->Front->Index;
		newnode->BackOrPolyCount = node->Back->Index;
	} else {
		newnode->FrontOrPoly0 = cur_poly | 0x80000000;
		newnode->BackOrPolyCount = node->PolyCount;
	}

	// Copy the polygon indices for this node into our array
	for (int pcounter = 0; pcounter < node->PolyCount; pcounter++) {
		poly_indices[cur_poly++] = node->PolyIndices[pcounter];
	}

	// Install the children
	if (node->Front) {
		Build_W3D_AABTree_Recursive(node->Front, w3d_nodes, poly_indices, cur_node, cur_poly);
	}
	if (node->Back) {
		Build_W3D_AABTree_Recursive(node->Back, w3d_nodes, poly_indices, cur_node, cur_poly);
	}
}

// FUNCTION: BFME2 0x00199280 size=588 name=?Compute_Plane_Score@AABTreeBuilderClass@@AAE?AUSplitChoiceStruct@1@HPAHABVAAPlaneClass@@@Z evidence=N:ledger tier=L hypothesis:name:L
AABTreeBuilderClass::SplitChoiceStruct AABTreeBuilderClass::Compute_Plane_Score(int polycount, int *polyindices, const AAPlaneClass &plane)
{
	SplitChoiceStruct sc;
	sc.Plane = plane;

	for (int i = 0; i < polycount; i++) {
		switch (Which_Side(plane, polyindices[i])) {
		case FRONT:
		case ON:
		case BOTH:
		{
			sc.FrontCount++;
			Update_Min_Max(polyindices[i], sc.FMin, sc.FMax);
			break;
		}
		case BACK:
		{
			sc.BackCount++;
			Update_Min_Max(polyindices[i], sc.BMin, sc.BMax);
			break;
		}
		}
	}

	// Pad the bounding boxes a little so degenerate boxes still have volume
	sc.BMin.X -= 0.0001f;
	sc.BMin.Y -= 0.0001f;
	sc.BMin.Z -= 0.0001f;
	sc.BMax.X += 0.0001f;
	sc.BMax.Y += 0.0001f;
	sc.BMax.Z += 0.0001f;

	float back_cost = (sc.BMax.X - sc.BMin.X) * (sc.BMax.Y - sc.BMin.Y) * (sc.BMax.Z - sc.BMin.Z) * sc.BackCount;
	float front_cost = (sc.FMax.X - sc.FMin.X) * (sc.FMax.Y - sc.FMin.Y) * (sc.FMax.Z - sc.FMin.Z) * sc.FrontCount;

	sc.Cost = front_cost + back_cost;

	// if this is a degenerate partition, mark it as a bad one
	if ((sc.FrontCount == 0) || (sc.BackCount == 0)) {
		sc.Cost = FLT_MAX;
	}

	return sc;
}

// FUNCTION: BFME2 0x001994E0 size=349 name=?Compute_Bounding_Box@AABTreeBuilderClass@@AAEXPAUCullNodeStruct@1@@Z evidence=N:ledger tier=L hypothesis:name:L
void AABTreeBuilderClass::Compute_Bounding_Box(CullNodeStruct *node)
{
	// compute bounding volumes of the children
	if (node->Front) {
		Compute_Bounding_Box(node->Front);
	}
	if (node->Back) {
		Compute_Bounding_Box(node->Back);
	}

	// compute bounding volume for the polys in this node
	const float really_big = FLT_MAX;
	node->Min.Set(really_big, really_big, really_big);
	node->Max.Set(-really_big, -really_big, -really_big);

	for (int poly_index = 0; poly_index < node->PolyCount; poly_index++) {
		Update_Min_Max(node->PolyIndices[poly_index], node->Min, node->Max);
	}

	// bound the children
	if (node->Front) {
		if (node->Front->Min.X < node->Min.X) node->Min.X = node->Front->Min.X;
		if (node->Front->Max.X > node->Max.X) node->Max.X = node->Front->Max.X;
		if (node->Front->Min.Y < node->Min.Y) node->Min.Y = node->Front->Min.Y;
		if (node->Front->Max.Y > node->Max.Y) node->Max.Y = node->Front->Max.Y;
		if (node->Front->Min.Z < node->Min.Z) node->Min.Z = node->Front->Min.Z;
		if (node->Front->Max.Z > node->Max.Z) node->Max.Z = node->Front->Max.Z;
	}

	if (node->Back) {
		if (node->Back->Min.X < node->Min.X) node->Min.X = node->Back->Min.X;
		if (node->Back->Max.X > node->Max.X) node->Max.X = node->Back->Max.X;
		if (node->Back->Min.Y < node->Min.Y) node->Min.Y = node->Back->Min.Y;
		if (node->Back->Max.Y > node->Max.Y) node->Max.Y = node->Back->Max.Y;
		if (node->Back->Min.Z < node->Min.Z) node->Min.Z = node->Back->Min.Z;
		if (node->Back->Max.Z > node->Max.Z) node->Max.Z = node->Back->Max.Z;
	}
}

