// FUNCTION: BFME2 0x00199680 size=398 name=?Export@AABTreeBuilderClass@@QAEXAAVChunkSaveClass@@@Z evidence=N:ledger tier=B hypothesis:K
void AABTreeBuilderClass::Export(ChunkSaveClass &csave)
{
	csave.Begin_Chunk(W3D_CHUNK_AABTREE);

	// Build the tree into W3D structures first
	W3dMeshAABTreeNode *nodes = new W3dMeshAABTreeNode[Node_Count()];
	unsigned long *poly_indices = new unsigned long[Poly_Count()];

	int cur_node = 0;
	int cur_poly = 0;
	Build_W3D_AABTree_Recursive(Root, nodes, poly_indices, cur_node, cur_poly);

	// Write out the header
	csave.Begin_Chunk(W3D_CHUNK_AABTREE_HEADER);
	W3dMeshAABTreeHeader header;
	memset(&header, 0, sizeof(header));
	header.NodeCount = Node_Count();
	header.PolyCount = Poly_Count();
	csave.Write(&header, sizeof(header));
	csave.End_Chunk();

	// Write out the polygon indices
	csave.Begin_Chunk(W3D_CHUNK_AABTREE_POLYINDICES);
	csave.Write(poly_indices, Poly_Count() * sizeof(unsigned long));
	csave.End_Chunk();

	// Write out the nodes
	csave.Begin_Chunk(W3D_CHUNK_AABTREE_NODES);
	for (int ni = 0; ni < Node_Count(); ni++) {
		csave.Write(&(nodes[ni]), sizeof(W3dMeshAABTreeNode));
	}
	csave.End_Chunk();

	csave.End_Chunk();
}

// FUNCTION: BFME2 0x00199810 size=712 name=?Select_Splitting_Plane@AABTreeBuilderClass@@AAE?AUSplitChoiceStruct@1@HPAH@Z evidence=N:ledger tier=B hypothesis:K
AABTreeBuilderClass::SplitChoiceStruct AABTreeBuilderClass::Select_Splitting_Plane(int polycount, int *polyindices)
{
	const int NUM_TRYS = 50;

	SplitChoiceStruct best_plane_stats;
	SplitChoiceStruct considered_plane_stats;

	// Try putting axis-aligned planes at some of the vertices
	for (int trys = 0; trys < ((NUM_TRYS < polycount) ? NUM_TRYS : polycount); trys++) {
		AAPlaneClass plane;

		// pick a random triangle and vertex
		int poly_index = polyindices[rand() % polycount];
		int vert_index = rand() % 3;
		const TriIndex *polyverts = Polys + poly_index;
		const Vector3 *vert = Verts + (*polyverts)[vert_index];

		// select a random axis for the plane
		switch (rand() % 3) {
		case 0:
			plane.Normal = AAPlaneClass::XNORMAL;
			plane.Dist = vert->X;
			break;
		case 1:
			plane.Normal = AAPlaneClass::YNORMAL;
			plane.Dist = vert->Y;
			break;
		case 2:
			plane.Normal = AAPlaneClass::ZNORMAL;
			plane.Dist = vert->Z;
			break;
		};

		considered_plane_stats = Compute_Plane_Score(polycount, polyindices, plane);

		if (considered_plane_stats.Cost < best_plane_stats.Cost) {
			best_plane_stats = considered_plane_stats;
		}
	}

	return best_plane_stats;
}

// FUNCTION: BFME2 0x00199AE0 size=495 name=?Build_Tree@AABTreeBuilderClass@@AAEXPAUCullNodeStruct@1@HPAH@Z evidence=N:ledger tier=B hypothesis:K
void AABTreeBuilderClass::Build_Tree(CullNodeStruct *node, int polycount, int *polyindices)
{
	// If there are only a few polys left, just terminate the tree
	if (polycount <= MIN_POLYS_PER_NODE) {
		node->PolyCount = polycount;
		node->PolyIndices = polyindices;
		return;
	}

	// Try to find a suitable partitioning plane
	SplitChoiceStruct sc;
	sc = Select_Splitting_Plane(polycount, polyindices);

	// If the split is degenerate, terminate the tree
	if (sc.FrontCount + sc.BackCount != polycount) {
		node->PolyCount = polycount;
		node->PolyIndices = polyindices;
		return;
	}

	// Split the polys with the selected plane and recurse
	SplitArraysStruct arrays;
	Split_Polys(polycount, polyindices, sc, &arrays);

	// free the memory in the original polyindices array
	delete[] polyindices;

	// Build the front tree
	if (arrays.FrontCount) {
		node->Front = new CullNodeStruct;
		Build_Tree(node->Front, arrays.FrontCount, arrays.FrontPolys);
		arrays.FrontPolys = NULL;
	}

	// Build the back tree
	if (arrays.BackCount) {
		node->Back = new CullNodeStruct;
		Build_Tree(node->Back, arrays.BackCount, arrays.BackPolys);
		arrays.BackPolys = NULL;
	}
}

// FUNCTION: BFME2 0x00199CD0 size=341 name=?Build_AABTree@AABTreeBuilderClass@@QAEXHPAVVector3i16@@HPAVVector3@@@Z evidence=N:ledger tier=B hypothesis:Z
void AABTreeBuilderClass::Build_AABTree(int polycount, TriIndex *polys, int vertcount, Vector3 *verts)
{
	// Copy the mesh data
	Reset();
	VertCount = vertcount;
	PolyCount = polycount;
	Verts = new Vector3[VertCount];
	Polys = new TriIndex[PolyCount];

	int vi;
	for (vi = 0; vi < VertCount; vi++) {
		Verts[vi] = verts[vi];
	}

	int pi;
	for (pi = 0; pi < PolyCount; pi++) {
		Polys[pi] = polys[pi];
	}

	// Build the tree: start with the full set of polygon indices
	int *polyindices = new int[PolyCount];
	for (int i = 0; i < PolyCount; i++) {
		polyindices[i] = i;
	}

	Root = new CullNodeStruct;
	Build_Tree(Root, PolyCount, polyindices);

	// Compute bounding volumes, then assign the node indices
	polyindices = NULL;
	Compute_Bounding_Box(Root);
	Assign_Index(Root, 0);
}

// FUNCTION: BFME2 0x00199E30 size=373 name=?Build_AABTree@AABTreeBuilderClass@@QAEXHPAVVector3i@@HPAVVector3@@@Z evidence=N:ledger tier=B hypothesis:Z

